package com.kovian.finance.debt.repository; import com.kovian.finance.debt.domain.Debt; import com.kovian.finance.debt.domain.DebtStatus; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface DebtRepository extends JpaRepository<Debt,UUID>{List<Debt> findByOwnerIdOrderByName(UUID o);List<Debt> findByStatusOrderByUpdatedAtDesc(DebtStatus status);Optional<Debt> findByIdAndOwnerId(UUID id,UUID o);}